window.docContents[204].resolve({"/Overview/#Cvc___lean----High-Level-CVC5-API--Overview--Arrays":{"contents":"An SMT array is total, so its Lean counterpart is Cvc.TotalMap ι κ: a default element plus the\nindices that differ from it. A model's array comes back as one. Constant arrays need cvc5's\narrays-exp option.\n\n#eval Env.runIO do\n  let solver ← Solver.new\n  solver.setOption \"produce-models\" \"true\"\n  solver.setOption \"arrays-exp\" \"true\"\n  let a ← solver.declareConst (TotalMap Int Int) \"a\"\n  let zero ← Term.mkInt 0\n  let zeros : Term (TotalMap Int Int) ←\n    Term.mkConstArray zero\n  let three ← Term.mkInt 3\n\n  -- `a` is all zeros, except perhaps at index 3...\n  let reset ← a.store three zero\n  smt! reset = zeros >>= solver.assert\n  -- ...where it is 42\n  let at3 ← a.select three\n  smt! at3 = 42 >>= solver.assert\n  solver.checkSat (ifSat := do\n    println! \"a := {← solver.getValue a}\")\n\n  -- reading back what was just written succeeds\n  let i ← solver.declareConst Int \"i\"\n  let v ← solver.declareConst Int \"v\"\n  let read ← (← a.store i v).select i\n  solver.checkSat (assuming := #[← smt! ¬ (read = v)])\n    (ifUnsat := println! \"select (store a i v) i = v\")\n\n\na := { 3 ↦ 42, _ ↦ 0 }\nselect (store a i v) i = v\n\n\n","context":"Cvc.lean -- High-Level CVC5 API\u0009Overview","header":"1.10. Arrays","id":"/Overview/#Cvc___lean----High-Level-CVC5-API--Overview--Arrays"}});